from pathlib import Path


def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f'{label}: target not found')
    return text.replace(old, new, 1)

tr_path = Path('TimeRange.js')
tr = tr_path.read_text()

tr = replace_once(
    tr,
    '''            this.#updateClipPath();\n            this.#animateOpacityIn();\n        }\n        else {''',
    '''            this.#updateClipPath();\n        }\n        else {''',
    'full-entry opacity removal'
)

anchor = '''    #getEndTime() {\n        return this.#endTime;\n    }\n'''
transition_method = '''    transitionTo({\n        startTime,\n        endTime\n    } = {}) {\n        const start =\n            this.#uniformDate(\n                startTime,\n                false\n            );\n\n        const end =\n            this.#uniformDate(\n                endTime,\n                false\n            );\n\n        if (\n            !(start instanceof Date) ||\n            !(end instanceof Date) ||\n            end.getTime() <=\n                start.getTime()\n        ) {\n            return false;\n        }\n\n        this.#syncing++;\n\n        try {\n            this.#startTime =\n                start;\n\n            this.#endTime =\n                end;\n\n            this.#rangeLength =\n                end.getTime() -\n                start.getTime();\n\n            this.#writeStartTimeAttribute();\n            this.#writeEndTimeAttribute();\n            this.#writeRangeLengthAttribute();\n        } finally {\n            this.#syncing--;\n        }\n\n        if (this.isConnected) {\n            this.#animateToLogicalTiming();\n        }\n\n        return true;\n    }\n\n'''
tr = replace_once(tr, anchor, transition_method + anchor, 'transitionTo insertion')
tr_path.write_text(tr)

ct_path = Path('ClockTimer.js')
ct = ct_path.read_text()

ct = replace_once(
    ct,
    '''        #preserveInsertedOnClear =\n            false;\n''',
    '''        #preserveInsertedOnClear =\n            false;\n\n        #starting =\n            false;\n''',
    'starting field'
)

old_start_build = '''            this.#buildPlannedRanges();\n\n            this.#renderAllInsertedRanges();\n\n            this.#refreshRingLayout(\n                this.#getCurrentTimelineTime(),\n                {\n                    refreshTickMarks: true\n                }\n            );\n\n            this.#startTickTimer();\n'''
new_start_build = '''            this.#starting =\n                true;\n\n            try {\n                this.#buildPlannedRanges();\n\n                this.#renderAllInsertedRanges();\n\n                this.#refreshRingLayout(\n                    this.#getCurrentTimelineTime(),\n                    {\n                        refreshTickMarks: true\n                    }\n                );\n            }\n            finally {\n                this.#starting =\n                    false;\n            }\n\n            this.#animateStartedRingWidths();\n\n            this.#startTickTimer();\n'''
ct = replace_once(ct, old_start_build, new_start_build, 'start special animation')

old_clear_loop = '''                for (\n                    const ring of\n                    this.querySelectorAll(\n                        ":scope > ring-container[data-clock-timer-ring]"\n                    )\n                ) {\n                    ring.removeAttribute(\n                        "data-clock-timer-ring"\n                    );\n\n                    ring.setAttribute(\n                        "data-clock-timer-exiting-ring",\n                        ""\n                    );\n\n                    const ranges =\n                        Array.from(\n                            ring.querySelectorAll(\n                                ":scope > time-range"\n                            )\n                        );\n\n                    for (\n                        const range of ranges\n                    ) {\n                        if (\n                            typeof range.removeAnimated ===\n                                "function"\n                        ) {\n                            range.removeAnimated({\n                                collapseTo: "start"\n                            });\n                        }\n                        else {\n                            range.remove();\n                        }\n                    }\n\n                    const TimeRangeClass =\n                        customElements.get(\n                            "time-range"\n                        );\n\n                    const duration =\n                        TimeRangeClass\n                            ? TimeRangeClass.animationDuration\n                            : 0;\n\n                    setTimeout(\n                        () => ring.remove(),\n                        Math.max(\n                            0,\n                            duration\n                        )\n                    );\n                }\n'''
new_clear_loop = '''                const duration =\n                    this.#getRangeAnimationDuration();\n\n                for (\n                    const ring of\n                    this.querySelectorAll(\n                        ":scope > ring-container[data-clock-timer-ring]"\n                    )\n                ) {\n                    ring.removeAttribute(\n                        "data-clock-timer-ring"\n                    );\n\n                    ring.setAttribute(\n                        "data-clock-timer-exiting-ring",\n                        ""\n                    );\n\n                    ring.resizeDuration =\n                        `${duration}ms`;\n\n                    ring.setAttribute(\n                        "width",\n                        "0px"\n                    );\n\n                    setTimeout(\n                        () => ring.remove(),\n                        duration\n                    );\n                }\n'''
ct = replace_once(ct, old_clear_loop, new_clear_loop, 'clear reverse animation')

old_handler = '''        #handlePercentGoalChange() {\n            const goal =\n                this.#getPercentGoal();\n\n            this.#percentGoal =\n                goal;\n\n            if (\n                !this.#started\n            ) {\n                return;\n            }\n\n            this.#removePlannedRanges();\n\n            this.#removeOvertimeRanges();\n\n            this.#buildPlannedRanges();\n\n            const now =\n                this.#getCurrentTimelineTime();\n\n            this.#updateElapsedRange(\n                now\n            );\n\n            this.#updateOvertimeRanges(\n                now\n            );\n\n            this.#refreshRingLayout(\n                now,\n                {\n                    refreshTickMarks: true\n                }\n            );\n        }\n'''
new_handler = '''        #handlePercentGoalChange() {\n            const goal =\n                this.#getPercentGoal();\n\n            this.#percentGoal =\n                goal;\n\n            if (\n                !this.#started\n            ) {\n                return;\n            }\n\n            this.#reconcilePlannedRanges();\n\n            this.#removeOvertimeRanges();\n\n            const now =\n                this.#getCurrentTimelineTime();\n\n            this.#updateElapsedRange(\n                now\n            );\n\n            this.#updateOvertimeRanges(\n                now\n            );\n\n            this.#refreshRingLayout(\n                now,\n                {\n                    refreshTickMarks: true\n                }\n            );\n        }\n'''
ct = replace_once(ct, old_handler, new_handler, 'percent goal handler')

old_set_timing = '''        #setRangeTiming(\n            range,\n            start,\n            end,\n            preserveRangeLength = false\n        ) {\n            range.setAttribute(\n                "start-time",\n                this.#formatTimelineTime(\n                    start\n                )\n            );\n\n            range.setAttribute(\n                "end-time",\n                this.#formatTimelineTime(\n                    end\n                )\n            );\n\n            if (\n                preserveRangeLength\n            ) {\n                range.setAttribute(\n                    "range-length",\n                    this.#formatStandardTime(\n                        end - start\n                    )\n                );\n            }\n            else {\n                range.removeAttribute(\n                    "range-length"\n                );\n            }\n\n            range.dataset.clockTimerStart =\n                String(start);\n\n            range.dataset.clockTimerEnd =\n                String(end);\n        }\n'''
new_set_timing = '''        #setRangeTiming(\n            range,\n            start,\n            end,\n            preserveRangeLength = false\n        ) {\n            const startTime =\n                this.#formatTimelineTime(\n                    start\n                );\n\n            const endTime =\n                this.#formatTimelineTime(\n                    end\n                );\n\n            if (\n                typeof range.transitionTo ===\n                    "function"\n            ) {\n                range.transitionTo({\n                    startTime,\n                    endTime\n                });\n            }\n            else {\n                range.setAttribute(\n                    "start-time",\n                    startTime\n                );\n\n                range.setAttribute(\n                    "end-time",\n                    endTime\n                );\n            }\n\n            if (\n                preserveRangeLength\n            ) {\n                range.setAttribute(\n                    "range-length",\n                    this.#formatStandardTime(\n                        end - start\n                    )\n                );\n            }\n            else {\n                range.removeAttribute(\n                    "range-length"\n                );\n            }\n\n            range.dataset.clockTimerStart =\n                String(start);\n\n            range.dataset.clockTimerEnd =\n                String(end);\n        }\n'''
ct = replace_once(ct, old_set_timing, new_set_timing, 'atomic timing transition')

old_replace_segments = '''            range.remove();\n\n            let firstSegment =\n                true;\n'''
new_replace_segments = '''            let firstSegment =\n                true;\n'''
ct = replace_once(ct, old_replace_segments, new_replace_segments, 'range segment preservation')

old_segment_append = '''                    const ring =\n                        this.#ensureRing(\n                            ringIndex\n                        );\n\n                    ring.appendChild(\n                        segment\n                    );\n\n                    firstSegment =\n                        false;\n'''
new_segment_append = '''                    const ring =\n                        this.#ensureRing(\n                            ringIndex\n                        );\n\n                    if (\n                        segment === range &&\n                        range.parentElement !== ring\n                    ) {\n                        if (\n                            typeof range.removeAnimated ===\n                                "function"\n                        ) {\n                            range.removeAnimated({\n                                collapseTo: "end"\n                            });\n                        }\n                        else {\n                            range.remove();\n                        }\n\n                        const movedSegment =\n                            document.createElement(\n                                "time-range"\n                            );\n\n                        this.#applyPreservedAttributes(\n                            movedSegment,\n                            preservedAttributes\n                        );\n\n                        this.#setRangeTiming(\n                            movedSegment,\n                            cursor,\n                            segmentEnd,\n                            preserveRangeLength\n                        );\n\n                        ring.appendChild(\n                            movedSegment\n                        );\n                    }\n                    else if (\n                        segment.parentElement !== ring\n                    ) {\n                        ring.appendChild(\n                            segment\n                        );\n                    }\n\n                    firstSegment =\n                        false;\n'''
ct = replace_once(ct, old_segment_append, new_segment_append, 'segment append behavior')

# Add helpers before #getPercentGoal.
helper_anchor = '''        #getPercentGoal() {\n'''
helpers = '''        #getRangeAnimationDuration() {\n            const TimeRangeClass =\n                customElements.get(\n                    "time-range"\n                );\n\n            const duration =\n                Number(\n                    TimeRangeClass\n                        ?.animationDuration\n                );\n\n            return (\n                Number.isFinite(duration) &&\n                duration >= 0\n            )\n                ? duration\n                : 0;\n        }\n\n        #getPlannedSegments() {\n            const spans = [];\n\n            if (\n                this.#startTimeMilliseconds !==\n                    undefined &&\n                this.#scheduledStartMilliseconds >\n                    this.#startTimeMilliseconds\n            ) {\n                spans.push({\n                    type: "early-start",\n                    start: this.#startTimeMilliseconds,\n                    end: this.#scheduledStartMilliseconds\n                });\n            }\n\n            if (\n                this.#startTimeMilliseconds !==\n                    undefined &&\n                this.#startTimeMilliseconds >\n                    this.#scheduledStartMilliseconds\n            ) {\n                spans.push({\n                    type: "late-start",\n                    start: this.#scheduledStartMilliseconds,\n                    end: this.#startTimeMilliseconds\n                });\n            }\n\n            const tripStart =\n                this.#scheduledStartMilliseconds;\n\n            this.#standardEnd =\n                tripStart +\n                this.#standardDuration;\n\n            this.#calculatedEnd =\n                tripStart +\n                (\n                    this.#standardDuration /\n                    this.#percentGoal\n                );\n\n            if (this.#percentGoal > 1) {\n                this.#tripEnd =\n                    this.#calculatedEnd;\n\n                this.#toleranceEnd =\n                    this.#standardEnd;\n\n                spans.push({\n                    type: "trip",\n                    start: tripStart,\n                    end: this.#calculatedEnd\n                });\n\n                spans.push({\n                    type: "tolerance",\n                    start: this.#calculatedEnd,\n                    end: this.#standardEnd\n                });\n            }\n            else {\n                this.#tripEnd =\n                    this.#standardEnd;\n\n                this.#toleranceEnd =\n                    undefined;\n\n                spans.push({\n                    type: "trip",\n                    start: tripStart,\n                    end: this.#standardEnd\n                });\n\n                if (this.#percentGoal < 1) {\n                    spans.push({\n                        type: "overtime",\n                        start: this.#standardEnd,\n                        end: this.#calculatedEnd\n                    });\n                }\n            }\n\n            const segments = [];\n\n            for (const span of spans) {\n                let cursor =\n                    span.start;\n\n                while (cursor < span.end) {\n                    const ringIndex =\n                        this.#getRingIndex(\n                            cursor\n                        );\n\n                    const ringEnd =\n                        this.#getRingStart(\n                            ringIndex\n                        ) +\n                        ClockTimer.#HOUR;\n\n                    const segmentEnd =\n                        Math.min(\n                            span.end,\n                            ringEnd\n                        );\n\n                    segments.push({\n                        type: span.type,\n                        start: cursor,\n                        end: segmentEnd,\n                        ringIndex\n                    });\n\n                    cursor =\n                        segmentEnd;\n                }\n            }\n\n            return segments;\n        }\n\n        #reconcilePlannedRanges() {\n            const desired =\n                this.#getPlannedSegments();\n\n            const existing =\n                Array.from(\n                    this.querySelectorAll(\n                        ':scope > ring-container > time-range[data-clock-timer-planned]:not([data-time-range-exiting])'\n                    )\n                );\n\n            const unused =\n                new Set(existing);\n\n            for (const target of desired) {\n                let match;\n                let bestScore =\n                    -Infinity;\n\n                for (const candidate of unused) {\n                    if (\n                        candidate.getAttribute(\n                            "type"\n                        ) !== target.type\n                    ) {\n                        continue;\n                    }\n\n                    const candidateRing =\n                        Number(\n                            candidate.parentElement\n                                ?.dataset.clockTimerRingIndex\n                        );\n\n                    if (\n                        candidateRing !==\n                            target.ringIndex\n                    ) {\n                        continue;\n                    }\n\n                    const oldStart =\n                        Number(\n                            candidate.dataset.clockTimerStart\n                        );\n\n                    const oldEnd =\n                        Number(\n                            candidate.dataset.clockTimerEnd\n                        );\n\n                    const overlap =\n                        Number.isFinite(oldStart) &&\n                        Number.isFinite(oldEnd)\n                            ? Math.max(\n                                0,\n                                Math.min(oldEnd, target.end) -\n                                Math.max(oldStart, target.start)\n                            )\n                            : 0;\n\n                    const distance =\n                        Number.isFinite(oldStart) &&\n                        Number.isFinite(oldEnd)\n                            ? Math.abs(oldStart - target.start) +\n                                Math.abs(oldEnd - target.end)\n                            : Number.MAX_SAFE_INTEGER;\n\n                    const score =\n                        overlap > 0\n                            ? overlap\n                            : -distance;\n\n                    if (score > bestScore) {\n                        bestScore = score;\n                        match = candidate;\n                    }\n                }\n\n                const ring =\n                    this.#ensureRing(\n                        target.ringIndex\n                    );\n\n                if (match) {\n                    unused.delete(match);\n\n                    this.#setRangeTiming(\n                        match,\n                        target.start,\n                        target.end\n                    );\n                }\n                else {\n                    const range =\n                        this.#createTimeRange(\n                            target.type,\n                            target.start,\n                            target.end\n                        );\n\n                    ring.appendChild(range);\n                }\n            }\n\n            for (const range of unused) {\n                if (\n                    typeof range.removeAnimated ===\n                        "function"\n                ) {\n                    range.removeAnimated({\n                        collapseTo: "end"\n                    });\n                }\n                else {\n                    range.remove();\n                }\n            }\n        }\n\n        #animateStartedRingWidths() {\n            const duration =\n                this.#getRangeAnimationDuration();\n\n            const rings =\n                Array.from(\n                    this.querySelectorAll(\n                        ":scope > ring-container[data-clock-timer-ring]"\n                    )\n                );\n\n            if (rings.length === 0) {\n                return;\n            }\n\n            requestAnimationFrame(\n                () => {\n                    for (const ring of rings) {\n                        if (!ring.isConnected) {\n                            continue;\n                        }\n\n                        ring.resizeDuration =\n                            `${duration}ms`;\n\n                        const targetWidth =\n                            ring.dataset.clockTimerTargetWidth;\n\n                        if (targetWidth) {\n                            ring.setAttribute(\n                                "width",\n                                targetWidth\n                            );\n\n                            delete ring.dataset.clockTimerTargetWidth;\n                        }\n                    }\n                }\n            );\n        }\n\n'''
ct = replace_once(ct, helper_anchor, helpers + helper_anchor, 'animation/reconcile helpers')

old_create_range_marker = '''            range.setAttribute(\n                "end-time",\n                this.#formatTimelineTime(\n                    end\n                )\n            );\n\n            range.dataset.clockTimerStart =\n'''
new_create_range_marker = '''            range.setAttribute(\n                "end-time",\n                this.#formatTimelineTime(\n                    end\n                )\n            );\n\n            if (this.#starting) {\n                range.setAttribute(\n                    "data-time-range-full-entry",\n                    ""\n                );\n            }\n\n            range.dataset.clockTimerStart =\n'''
ct = replace_once(ct, old_create_range_marker, new_create_range_marker, 'start range full geometry')

old_ensure_width = '''            ring.setAttribute(\n                "width",\n                "var(--clock-timer-active-ring-width, clamp(2px, 1.25cqi, 6px))"\n            );\n'''
new_ensure_width = '''            const initialWidth =\n                "var(--clock-timer-active-ring-width, clamp(2px, 1.25cqi, 6px))";\n\n            if (this.#starting) {\n                ring.dataset.clockTimerTargetWidth =\n                    initialWidth;\n\n                ring.setAttribute(\n                    "width",\n                    "0px"\n                );\n\n                ring.resizeDuration =\n                    `${this.#getRangeAnimationDuration()}ms`;\n            }\n            else {\n                ring.setAttribute(\n                    "width",\n                    initialWidth\n                );\n            }\n'''
ct = replace_once(ct, old_ensure_width, new_ensure_width, 'ensure ring start width')

old_reorder_width = '''                if (\n                    ring.getAttribute(\n                        "width"\n                    ) !==\n                        width\n                ) {\n                    ring.setAttribute(\n                        "width",\n                        width\n                    );\n                }\n'''
new_reorder_width = '''                if (this.#starting) {\n                    ring.dataset.clockTimerTargetWidth =\n                        width;\n\n                    if (\n                        ring.getAttribute(\n                            "width"\n                        ) !== "0px"\n                    ) {\n                        ring.setAttribute(\n                            "width",\n                            "0px"\n                        );\n                    }\n                }\n                else if (\n                    ring.getAttribute(\n                        "width"\n                    ) !==\n                        width\n                ) {\n                    ring.setAttribute(\n                        "width",\n                        width\n                    );\n                }\n'''
ct = replace_once(ct, old_reorder_width, new_reorder_width, 'reorder start width hold')

# Manual open-ended inserted range also gets full geometry during start.
old_manual_insert = '''                range.setAttribute(\n                    "start-time",\n                    this.#formatTimelineTime(\n                        start\n                    )\n                );\n\n                range.dataset.clockTimerStart =\n'''
new_manual_insert = '''                range.setAttribute(\n                    "start-time",\n                    this.#formatTimelineTime(\n                        start\n                    )\n                );\n\n                if (this.#starting) {\n                    range.setAttribute(\n                        "data-time-range-full-entry",\n                        ""\n                    );\n                }\n\n                range.dataset.clockTimerStart =\n'''
ct = replace_once(ct, old_manual_insert, new_manual_insert, 'manual start range marker')

ct_path.write_text(ct)
